/** Current-run fields listed as int/int[] in data/player-stats field catalog.
 * They are distinct from purchased upgradeWorkshop* arrays. No stat-index or
 * active-session inference is made here.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    readCurrentRunFromSaveRoot
 * depends    src/save/current-run/types
 * used by    src/calculators/specs.generated, src/save/current-run/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { CurrentRunSaveExtract } from './types'

export function readCurrentRunFromSaveRoot(root: Record<string, unknown> | null): CurrentRunSaveExtract | null {
  if (!root) return null
  const unreadableKeys: string[] = []
  const integer = (value: unknown, key: string): number | null => {
    if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) return value
    unreadableKeys.push(key)
    return null
  }
  const levels = (key: string): (number | null)[] | null => {
    const value = root[key]
    if (!Array.isArray(value)) { unreadableKeys.push(key); return null }
    return value.map((entry, index) => integer(entry, `${key}[${index}]`))
  }
  return {
    currentWave: integer(root.currentWave, 'currentWave'),
    currentTier: integer(root.currentTier, 'currentTier'),
    upgradeLevel: levels('upgradeLevel'),
    upgradeDefenseLevel: levels('upgradeDefenseLevel'),
    upgradeUtilityLevel: levels('upgradeUtilityLevel'),
    unreadableKeys,
  }
}
